  var ROWS = 20;
  var COLS = 10;
  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
  var PREVIEW = 3;
  var GRAVITY_MS = 1000;
  var LOCK_DELAY_TICKS = 2;   // gravity steps a piece may spend unable to fall
  var MAX_LOCK_RESETS = 3;    // times per piece a sideways move or soft drop restarts the delay

  // Points for rows cleared at once, times the level. Clearing rows together
  // must always beat clearing the same rows one at a time.
  var CLEAR_POINTS = [0, 100, 300, 500, 800];
  var SOFT_DROP_POINTS = 1;   // per cell moved down by soft drop
  var HARD_DROP_POINTS = 2;   // per cell dropped by hard drop

  // Each shape is a square matrix; spawn puts its filled cells in rows 0-1.
  var SHAPES = {
    I: { m: ["....", "IIII", "....", "...."], row: -1, col: 3 },
    O: { m: ["OO", "OO"], row: 0, col: 4 },
    T: { m: [".T.", "TTT", "..."], row: 0, col: 3 },
    S: { m: [".SS", "SS.", "..."], row: 0, col: 3 },
    Z: { m: ["ZZ.", ".ZZ", "..."], row: 0, col: 3 },
    J: { m: ["J..", "JJJ", "..."], row: 0, col: 3 },
    L: { m: ["..L", "LLL", "..."], row: 0, col: 3 }
  };

  // ---- State ----
  var board;        // board[row][col] = "" or piece letter
  var current;      // { type, matrix, row, col, lockTicks, lockResets } or null
  var next;         // upcoming piece letters, soonest first
  var scripted;     // true while `next` comes from a test-supplied queue
  var bag = [];
  var score, level, lines, status;
  var timer = null;

  function emptyBoard() {
    var b = [];
    for (var r = 0; r < ROWS; r++) {
      var row = [];
      for (var c = 0; c < COLS; c++) row.push("");
      b.push(row);
    }
    return b;
  }

  function randomType() {
    if (bag.length === 0) {
      bag = TYPES.slice();
      for (var i = bag.length - 1; i > 0; i--) {
        var j = Math.floor(Math.random() * (i + 1));
        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
      }
    }
    return bag.pop();
  }

  function fillPreview() {
    if (scripted) return;
    while (next.length < PREVIEW) next.push(randomType());
  }

  function shapeCells(matrix, row, col) {
    var cells = [];
    for (var r = 0; r < matrix.length; r++) {
      for (var c = 0; c < matrix[r].length; c++) {
        if (matrix[r][c] !== ".") cells.push([row + r, col + c]);
      }
    }
    return cells;
  }

  function fits(matrix, row, col) {
    var cells = shapeCells(matrix, row, col);
    for (var i = 0; i < cells.length; i++) {
      var r = cells[i][0], c = cells[i][1];
      if (r < 0 || r >= ROWS || c < 0 || c >= COLS) return false;
      if (board[r][c] !== "") return false;
    }
    return true;
  }

  function spawn() {
    if (next.length === 0) scripted = false;
    fillPreview();
    var type = next.shift();
    fillPreview();
    var s = SHAPES[type];
    var piece = {
      type: type, matrix: s.m.slice(), row: s.row, col: s.col,
      lockTicks: 0,   // consecutive gravity steps spent unable to fall
      lockResets: 0   // lifetime count of lock-delay restarts
    };
    if (!fits(piece.matrix, piece.row, piece.col)) {
      current = null;
      status = "gameover";
      stopTimer();
  function paintCell(el, piece) {
    el.className = piece ? "cell p-" + piece : "cell";
    el.setAttribute("data-filled", piece ? "true" : "false");
    el.setAttribute("data-piece", piece);
  }

  function renderNext() {
    nextEl.textContent = "";
    for (var i = 0; i < Math.min(next.length, PREVIEW); i++) {
      var type = next[i];
      var m = SHAPES[type].m;
      var offset = type === "I" ? 1 : 0; // I's filled row is row 1 of its matrix
      var mini = document.createElement("div");
      mini.className = "mini";
      mini.setAttribute("data-testid", "next-piece-item");
      mini.setAttribute("data-piece", type);
      for (var r = 0; r < 2; r++) {
        for (var c = 0; c < 4; c++) {
          var ch = m[r + offset] && m[r + offset][c];
          var cell = document.createElement("div");
          cell.className = ch && ch !== "." ? "mini-cell p-" + type : "mini-cell";
          mini.appendChild(cell);
        }
      }
      nextEl.appendChild(mini);
    }
  }

  function render() {
    var view = board.map(function (row) { return row.slice(); });
    if (current) {
      var cells = shapeCells(current.matrix, current.row, current.col);
      for (var i = 0; i < cells.length; i++) {
        view[cells[i][0]][cells[i][1]] = current.type;
      }
    }
    for (var r = 0; r < ROWS; r++) {
      for (var c = 0; c < COLS; c++) paintCell(cellEls[r][c], view[r][c]);
    }
    scoreEl.textContent = String(score);
    levelEl.textContent = String(level);
    linesEl.textContent = String(lines);
    // The overlay is in the DOM only while the game is over.
    if (status === "gameover") {
      if (!overlayEl.parentNode) boardWrapEl.appendChild(overlayEl);
    } else if (overlayEl.parentNode) {
      overlayEl.parentNode.removeChild(overlayEl);
    }
    renderNext();
  }

  // ---- Game control ----
  function validTypes(queue) {
    if (!Array.isArray(queue)) return [];
    return queue.filter(function (t) { return SHAPES.hasOwnProperty(t); });
  }

  function newGame(queue) {
    board = emptyBoard();
    score = 0;
    level = 1;
    lines = 0;
    status = "running";
    current = null;
    bag = [];
    if (Array.isArray(queue)) {
      next = validTypes(queue);
      scripted = true;
    } else {
      next = [];
      scripted = false;
    }
    spawn();
    startTimer();
    render();
  }

  function setQueue(queue) {
    next = validTypes(queue);
    scripted = true;
    render();
  }

  function setBoard(rows) {
    var b = emptyBoard();
    for (var r = 0; r < ROWS; r++) {
      var line = (rows && rows[r]) || "";
      for (var c = 0; c < COLS; c++) {
        var ch = line.charAt(c);
        b[r][c] = SHAPES.hasOwnProperty(ch) ? ch : "";
      }
    }
    board = b;
    render();
  }

  function getBoard() {
    return board.map(function (row) {
      return row.map(function (v) { return v || "."; }).join("");
    });
  }

  function getState() {
    var cur = null;
    if (current) {
      var cells = shapeCells(current.matrix, current.row, current.col);
      cells.sort(function (a, b) { return a[0] - b[0] || a[1] - b[1]; });
      cur = { type: current.type, cells: cells };
    }
    return {
      current: cur,
      next: next.slice(),
      score: score,
      level: level,
      lines: lines,
      status: status
    };
  }

  function tick(n) {
    var steps = n === undefined ? 1 : Math.max(0, Math.floor(Number(n)) || 0);
    for (var i = 0; i < steps; i++) gravityStep();
    render();
  }

  window.__tetris = {
    newGame: newGame,
    setQueue: setQueue,
    setBoard: setBoard,
    tick: tick,
    input: function (action) { applyInput(action); render(); },

